    def test_recompare_lists_and_counts_rows_it_cannot_resolve(self):
        rows = [self._noaddr('CResEffect::Parse'), self._noaddr('Dup::Go')]
        self.write_disagreements([self._noaddr('Old::Gone', 'src/Z.cpp')])
        src = lambda f: self.SRC_A
