    def _amending_worker(self, command, amend):
        t = self._tcalls(('Bash', {'command': command}))
        w = self._twork([t])
        if amend:
            w.before = lambda cwd: subprocess.run(
                ['git', '-C', cwd, 'commit', '-q', '--amend', '--allow-empty', '-m', 'again'],
                check=True)
        return w

