        os.chmod(py, 0o755)
        calls = []
        with mock.patch.object(driver, '_vanilla_exe', return_value=exe), \
                mock.patch.dict(os.environ, {'IWD2R_HOME': d}):
            driver.mechanical_checks(batch, d, {'0x76D370': ('ours', 'c')},
                                     run=self._mc_run(0, calls))
