    def test_driver_frida_records_equal_and_flags_different(self):
        trace = TruthTest._trace
        for ours_ret, report, outcome in (
                (3, 'verdict 0x401000 ours case dump-401000\nverdict 0x402000 ours case dump-402000\n', 'equal'),
                (4, 'verdict 0x401000 ours case dump-401000\nverdict 0x402000 ours case dump-402000\n', 'different')):
            seen = []

            def frida_run(batch_id, table, scenarios, ours_ret=ours_ret, **kw):
                seen.append((batch_id, [h['name'] for h in table['original']['hooks']], list(scenarios)))
                return {'world_entry': (trace(('fn_402000', 7, 3)), trace(('fn_402000', 7, ours_ret)))}
            d = self._measured_driver(worker=_SeqWorker('# r\n\n## Verdicts\n\n' + report),
                                      frida=True, frida_build=self._frida_builder()[0],
                                      frida_run=frida_run,
                                      oracle_run=lambda *a: {'0x401000': ('pass', 'ok')})
            d.run_batch('b011')
            self.assertEqual(seen[0][1], ['fn_402000'])
            self.assertEqual(seen[0][0], 'b011')
            b = self._state()
            if outcome == 'equal':
                self.assertEqual(b['status'], 'closed')
                self.assertEqual(b['verdicts']['0x402000']['measured'], 'frida')
                self.assertEqual(b['verdicts']['0x401000']['measured'], 'probe')
            else:   # different while the worker keeps ours: one fix round (the finding), Frida ran once,
                # the verdict stays unmeasured and the ledger says so; no exception
                self.assertEqual(b['status'], 'closed')
                self.assertEqual(len(seen), 1)
                self.assertNotIn('measured', b['verdicts']['0x402000'])
                with open(os.path.join(os.path.dirname(d.status_path), 'b011', 'worker-fix-checks.brief.md')) as f:
                    self.assertIn('the Frida trace diff shows the body on the branch (verdict ours) '
                                  'different from the original', f.read())
                self.assertIn('- frida different, kept ours: 0x402000 differs in world_entry', self._ledger(d))

    def test_driver_frida_on_the_batch_build_equal_confirms_a_fork_verdict(self):
        # the phase measures the branch's body: for a fork verdict that is the
        # adopted fork body, so equal confirms it (measured frida, no finding)
        # and different is a finding
        trace = TruthTest._trace
        report = ('# r\n\n## Verdicts\n\nverdict 0x401000 ours case dump-401000\n'
                  'verdict 0x402000 fork case probe-12\n')
        for ours_ret, outcome in ((3, 'equal'), (4, 'different')):
            d = self._measured_driver(
                worker=_SeqWorker(report, report), frida=True, frida_build=self._frida_builder()[0],
                frida_run=lambda b, table, scenarios, r=ours_ret, **kw: {
                    'world_entry': (trace(('fn_402000', 7, 3)), trace(('fn_402000', 7, r)))},
                oracle_run=lambda *a: {})
            self.assertEqual(d.run_batch('b011'), 'closed', self._status(d)['exceptions'])
            v = self._state()['verdicts']['0x402000']
            self.assertEqual(v['side'], 'fork')
            fix = os.path.join(os.path.dirname(d.status_path), 'b011', 'worker-fix-checks.brief.md')
            if outcome == 'equal':
                self.assertEqual(v['measured'], 'frida')
                self.assertFalse(os.path.exists(fix))
                self.assertNotIn('recheck', self._ledger(d))
            else:
                self.assertNotIn('measured', v)
                with open(fix) as f:
                    self.assertIn('0x402000: the Frida trace diff shows the body on the branch '
                                  '(verdict fork) different from the original', f.read())
                self.assertIn('- frida different, kept fork: 0x402000 differs in world_entry',
                              self._ledger(d))

    # -- Task 20 part A: wave-1 equal rows get trace evidence --------------

    def _frida_file_run(self, ours_ret=3, dumps=True):
        """A frida_run whose traces are file-backed, fn_402000 returning 3 in the
        original and `ours_ret` in ours; the dumps match unless `dumps` is False."""
        trace = TruthTest._trace
        files = os.path.join(tempfile.mkdtemp(), 'traces')
        self.addCleanup(shutil.rmtree, os.path.dirname(files), True)
        os.makedirs(files)

        def frida_run(batch_id, table, scenarios, **kw):
            out = {}
            for sc in scenarios:
                orig, ours = trace(('fn_402000', 7, 3)), trace(('fn_402000', 7, ours_ret))
                paths = {}
                for side, ev in (('orig', orig), ('ours', ours)):
                    paths[side] = os.path.join(files, '%s-%s.jsonl' % (sc, side))
                    with open(paths[side], 'w') as f:
                        f.write(''.join(json.dumps(e) + '\n' for e in ev))
                out[sc] = {'orig': orig, 'ours': ours, 'orig_path': paths['orig'],
                           'ours_path': paths['ours'], 'failed': None,
                           'dumps': {'match': dumps, 'detail': 'fixture'}}
            return out
        return frida_run

    def _wave_frida_driver(self, report, ours_ret=3, dumps=True, kind='read-only', stem='402000',
                           worker=None):
        """A measured driver whose 0x402000 evidence is `kind` and whose Frida run
        returns file-backed traces (dumps match unless `dumps` is False)."""
        frida_run = self._frida_file_run(ours_ret, dumps)
        d = self._measured_driver(worker=worker or _SeqWorker(report), frida=True,
                                  frida_build=self._frida_builder()[0], frida_run=frida_run,
                                  oracle_run=lambda *a: {})
        path = os.path.join(self.wt, 'docs', 'evidence', stem + '.md')
        with open(path) as f:
            text = f.read()
        with open(path, 'w') as f:
            f.write(re.sub(r'^kind: \S+$', 'kind: %s' % kind + ('\nexemption: "a reading"' if kind == 'read-only' else ''),
                           text, count=1, flags=re.M))
        if self.git('status', '--porcelain', cwd=self.wt).stdout.strip():
            self.git('commit', '-qam', 'evidence kind', cwd=self.wt)
        return d

    WAVE_REPORT = ('# r\n\n## Verdicts\n\nverdict 0x401000 ours case dump-401000\n'
                   'verdict 0x402000 %s case %s\n')

    def _wave_fields(self, stem='402000'):
        with open(os.path.join(self.wt, 'docs', 'evidence', stem + '.md')) as f:
            text = f.read()
        return load_tool('check_evidence').front_matter(text), text

