    def test_a_batch_in_flight_that_also_reads_cleared_resumes_once(self):
        # b019 (2026-10-23): in flight at the stop AND listed by _cleared()
        # (its status entry kept outcome: exception after a --clear); it must
        # resume once, never also launch as a retry while it runs
        d = self._driver(worker=driver.FakeWorker(self.REPORT))
        os.makedirs(os.path.dirname(d.status_path))
        with open(d.status_path, 'w') as f:
            json.dump({'exceptions': {},
                       'batches': {'b011': {'outcome': 'exception', 'stage': 'checks'}},
                       'running': {'b011': {'stage': 'reviewer', 'pool': 'a',
                                            'at': '2026-10-23T20:00:00+00:00'}}}, f)
        d = self._reload(d)
        ran = []
        d.run_batch = lambda bid, resume=None: ran.append((bid, resume is not None)) or 'closed'
        d.next_batch = lambda *a, **kw: self.NOTHING
        self.assertEqual(d.run(), 0)
        self.assertEqual([b for b, _r in ran], ['b011'])

    def test_a_resume_finishing_after_exhaustion_earns_one_more_cut(self):
        # run 24 (2026-10-25): the cut's 'nothing left' verdict formed while
        # the retried batch still ran and owned its files, the run exited on
        # it, and run 25 cut two batches at once; a resumed or retried batch
        # that finishes after the verdict earns one more cut before the exit
        d = self._driver(worker=driver.FakeWorker(self.REPORT), workers=2)
        self._write_status(d, {'current': {'batch': 'b011', 'stage': 'worker',
                                           'at': '2026-10-24T01:00:00+00:00'}})
        verdict, ran, cuts = threading.Event(), [], []
        run24 = (2, 'nothing left: every remaining theirs_changed_ours_base row '
                   'is kept by default (1 recorded: no scenario exercises them)\n')

        def run_batch(bid, resume=None):
            ran.append((bid, resume is not None))
            if bid == 'b011':
                self.assertTrue(verdict.wait(10))  # the verdict forms while it runs
            return 'closed'

        def next_batch(*a, **kw):
            cuts.append(1)
            if len(cuts) == 1:
                verdict.set()
                return run24
            return (0, self.CUT.replace('b011', 'b012')) if len(cuts) == 2 \
                else self.NOTHING

        d.run_batch, d.next_batch = run_batch, next_batch
        self.assertEqual(d.run(), 0)
        self.assertEqual(ran, [('b011', True), ('b012', False)])
        self.assertEqual(len(cuts), 3)
        self.assertIn('b011 finished after the pool was judged exhausted; '
                      'trying one more cut', '\n'.join(self.logs))

    def test_run_retries_a_cleared_exception_first(self):
        d = self._driver(worker=driver.FakeWorker(self.REPORT))
        os.makedirs(os.path.dirname(d.status_path))
        with open(d.status_path, 'w') as f:
            json.dump({'exceptions': {}, 'batches': {'b011': {'outcome': 'exception'}}}, f)
        d = self._reload(d)
        ran = []
        d.run_batch = lambda bid, resume=None: ran.append(bid) or 'closed'
        d.next_batch = lambda *a, **kw: self.NOTHING
        self.assertEqual(d.run(), 0)
        self.assertEqual(ran, ['b011'])
        # Not while the exception is still in the status file.
        with open(d.status_path, 'w') as f:
            json.dump({'exceptions': {'b011': {'stage': 'checks'}},
                       'batches': {'b011': {'outcome': 'exception'}}}, f)
        d = self._reload(d)
        ran.clear()
        d.run_batch = lambda bid, resume=None: ran.append(bid) or 'closed'
        d.next_batch = lambda *a, **kw: self.NOTHING
        self.assertEqual(d.run(), 0)
        self.assertEqual(ran, [])

    def _live_clear_driver(self):
        """The first cut (b011) runs and blocks on `release`; b012 is
        assigned with an exception entry; the next cut would be b013."""
        d = self._driver(worker=driver.FakeWorker(self.REPORT))
        with open(self.state_path) as f:
            state = json.load(f)
        state['batches']['b012'] = dict(state['batches']['b011'], branch='p3/wso-b012')
        with open(self.state_path, 'w') as f:
            json.dump(state, f)
        os.makedirs(os.path.dirname(d.status_path))
        with open(d.status_path, 'w') as f:
            json.dump({'exceptions': {'b012': {'stage': 'checks'}}, 'running': {},
                       'batches': {'b012': {'outcome': 'exception',
                                            'stage': 'checks'}}}, f)
        d = self._reload(d)
        inside, release = threading.Event(), threading.Event()
        events = []

        def run_batch(bid, resume=None):
            events.append('run ' + bid)
            if bid == 'b011':
                inside.set()
                self.assertTrue(release.wait(10))
            return 'closed'
        d.run_batch = run_batch
        cuts = iter([(0, self.CUT), (0, self.CUT.replace('b011', 'b013')),
                     self.NOTHING])

        def cut(*a, **kw):
            events.append('cut')
            return next(cuts)
        d.next_batch = cut
        return d, inside, release, events

    def _edit_status(self, d, fn):
        with open(d.status_path) as f:
            status = json.load(f)
        fn(status)
        with open(d.status_path, 'w') as f:
            json.dump(status, f)

    def _run_with_clear(self, d, inside, release, edit):
        codes = []
        t = threading.Thread(target=lambda: codes.append(d.run()))
        t.start()
        try:
            self.assertTrue(inside.wait(10))
            self._edit_status(d, edit)
        finally:
            release.set()
            t.join(20)
        return codes

    def test_run_picks_up_an_exception_cleared_while_running(self):
        d, inside, release, events = self._live_clear_driver()
        codes = self._run_with_clear(
            d, inside, release, lambda s: s.__setitem__('exceptions', {}))
        self.assertEqual(codes, [0])
        # The cleared batch goes before the next cut, and only once.
        self.assertEqual(events, ['cut', 'run b011', 'run b012', 'cut',
                                  'run b013', 'cut'])
        line = ('b012: exception cleared while running; retrying at its '
                'checks stage')
        self.assertEqual(self.logs.count(line), 1)

    def test_live_clear_skips_a_batch_that_is_still_running(self):
        d, inside, release, events = self._live_clear_driver()

        def edit(s):
            s['exceptions'] = {}
            s['running'] = {'b012': {'at': 't'}}   # stale: its own retry
        codes = self._run_with_clear(d, inside, release, edit)
        self.assertEqual(codes, [0])
        self.assertNotIn('run b012', events)
        self.assertEqual([l for l in self.logs if 'cleared while running' in l], [])

    def _reload(self, d):
        """A fresh Driver over the same paths, reading the status file again."""
        n = driver.Driver(d.repo, d.state_path, d.worker, d.reviewer, d.ledger_path,
                          d.status_path, push=d.push, send=d.send, gate=False,
                          log=self.logs.append, base_tests=False)
        n.render_brief, n.mechanical_checks = d.render_brief, d.mechanical_checks
        n.report_path, n.triage_path = d.report_path, d.triage_path
        return n

