        b = state['batches']['b011']
        b['rows'].append({'address': '0x40B100', 'name': 'G', 'file': 'src/G.cpp',
                          'category': 'both_changed_differ', 'their_len': 1, 'our_len': 1})
        b['files'].append('src/G.cpp')
