    def test_sigterm_kills_the_workers_and_leaves_the_batch_running(self):
        sleeper = subprocess.Popen(['sleep', '60'], start_new_session=True)
        self.addCleanup(lambda: sleeper.poll() is None and sleeper.kill())
        w = self._BatchWorker(credits=0.0)

        def run(brief, cwd):
            driver._LIVE.add(sleeper.pid)
            os.kill(os.getpid(), signal.SIGTERM)
            time.sleep(5)                        # the handler raises before this ends
            self.fail('not stopped')
        w.run = run
        d = self._pool_driver(self._two_pools()[:1], {'a': w}, ids=('b011',))
        self.addCleanup(lambda: self.assertEqual(self.taskkills, []))   # a worker only: no taskkill
        before = (signal.getsignal(signal.SIGTERM), signal.getsignal(signal.SIGINT))
        with mock.patch.dict(os.environ, self.GIT_ENV):
            self.assertEqual(d.run(), 1)
        driver._LIVE.discard(sleeper.pid)
        self.assertIsNotNone(sleeper.wait(timeout=5))
        self.assertEqual((signal.getsignal(signal.SIGTERM), signal.getsignal(signal.SIGINT)), before)
        status = self._status(d)
        self.assertIn('b011', status['running'])
        self.assertEqual(status['exceptions'], {})
        self.assertEqual(self._state_of(d, 'b011')['status'], 'assigned')
        # The run lock was released: another run starts (and resumes b011).
        d.worker = d.workers_by_pool['a'] = self._BatchWorker(credits=0.0)
        self.pending[:] = []
        with mock.patch.dict(os.environ, self.GIT_ENV):
            self.assertEqual(d.run(), 0)

    # -- two workers per pool: the morning report's caveats --------------------

    def test_stop_handler_reentrant(self):
        """A signal can land while the same thread holds the live-groups
        lock: the handler must not deadlock on it."""
        done = threading.Event()
        self.addCleanup(driver._STOPPED.clear)

        def hold_and_kill():
            with driver._LIVE_LOCK:
                driver.kill_live_groups()
            done.set()
        t = threading.Thread(target=hold_and_kill, daemon=True)
        t.start()
        self.assertTrue(done.wait(5), 'kill_live_groups deadlocked on its own lock')

    def test_stop_waits_for_git_write(self):
        self.addCleanup(driver._STOPPED.clear)
        d = self._pool_driver(self._two_pools()[:1], {'a': None}, ids=('b011',))
        d.STOP_WAIT = 5
        inside, release = threading.Event(), threading.Event()
        finished = []

        def writer():
            with d._writing():
                inside.set()
                release.wait(10)
                finished.append(time.monotonic())
        t = threading.Thread(target=writer, daemon=True)
        t.start()
        self.assertTrue(inside.wait(5))
        threading.Timer(0.3, release.set).start()
        with self.assertRaises(driver._Stop):
            d._on_stop(signal.SIGTERM, None)
        raised = time.monotonic()
        t.join(5)
        self.assertTrue(finished and finished[0] <= raised,
                        'the stop was raised before the git write finished')
        self.assertTrue(d._stopping)

    def test_stop_wait_is_bounded(self):
        self.addCleanup(driver._STOPPED.clear)
        d = self._pool_driver(self._two_pools()[:1], {'a': None}, ids=('b011',))
        d.STOP_WAIT = 0.2
        inside, release = threading.Event(), threading.Event()

        def writer():
            with d._writing():
                inside.set()
                release.wait(10)
        t = threading.Thread(target=writer, daemon=True)
        t.start()
        self.assertTrue(inside.wait(5))
        start = time.monotonic()
        with self.assertRaises(driver._Stop):
            d._on_stop(signal.SIGTERM, None)
        self.assertLess(time.monotonic() - start, 3)
        release.set()
        t.join(5)

