class WaveResolveTest(unittest.TestCase):
    """wave.py resolve (a probe-list row into its batch) and the rule-3
    audit paragraph of the scorecard."""

    setUp = WaveTest.setUp
    PROBED = '0x716E80'
    ROW = {'address': '0x716E80', 'category': 'both_changed_differ',
           'class': 'ambiguous', 'file': 'src/CGameSprite.cpp',
           'name': 'CGameSprite::sub_716E80', 'our_len': 300, 'their_len': 310}

    def repo(self, evidence='disagreed with WSO at e8dd16a: x; case dump-716E80 decides\n',
             probes=True):
        self.root = os.path.join(self.tmp, 'repo')
        shutil.rmtree(self.root, ignore_errors=True)
        wso = os.path.join(self.root, 'docs', 'wso')
        first = dict(self.ROW, address='0x643CC0', name='Render')
        _write(os.path.join(wso, 'disagreements.json'),
               json.dumps([first, self.ROW]))
        self.state = os.path.join(wso, 'wave-state.json')
        self.wave.save_state(self.state, {'batches': {'b011': {
            'rows': [first], 'files': ['src/CGameSprite.cpp'],
            'branch': 'p3/wso-b011', 'status': 'closed', 'assigned_at': 't',
            'closed_at': 't', 'verdicts': {
                '0x643CC0': {'side': 'ours', 'case': 'probe-1',
                             'losing_kind': 'trace'}}}}})
        if probes:
            _write(os.path.join(wso, 'probe-list.json'), json.dumps([
                {'address': '0x716E80', 'at': 't', 'batch': 'b011',
                 'file': 'src/CGameSprite.cpp', 'name': 'CGameSprite::sub_716E80',
                 'reading': 'fork', 'reason': 'r', 'source': 'worker'}]))
        if evidence is not None:
            _write(os.path.join(self.root, 'docs', 'evidence', '716E80.md'),
                   '---\nkind: oracle\n---\n\n' + evidence)

    def resolve(self, side='ours', case='dump-716E80', address='0x716E80'):
        return self.wave.resolve_probe(address, side, case, self.state, self.root)

    def probe_list(self):
        with open(os.path.join(self.root, 'docs', 'wso', 'probe-list.json')) as f:
            return json.load(f)

    def test_resolve_probe_records_ours_verdict(self):
        self.repo()
        rc, out = self.resolve()
        self.assertEqual(rc, 0, out)
        self.assertEqual(out, 'resolved 0x716E80 in b011: ours (case dump-716E80); '
                              'probe list now 0 entries\n')
        b = self.wave.load_state(self.state)['batches']['b011']
        self.assertEqual([r['address'] for r in b['rows']], ['0x643CC0', '0x716E80'])
        self.assertEqual(sorted(b['rows'][1]), sorted(b['rows'][0]))
        self.assertEqual(b['rows'][1], self.ROW)
        self.assertEqual(b['rows'][1]['class'], 'ambiguous')
        self.assertIn('src/CGameSprite.cpp', b['files'])
        self.assertEqual(b['files'], self.wave._files_of(b['rows']))
        self.assertEqual(b['verdicts']['0x716E80'],
                         {'side': 'ours', 'case': 'dump-716E80',
                          'losing_kind': 'trace', 'measured': 'none'})
        self.assertEqual(b['status'], 'closed')
        self.assertEqual(self.probe_list(), [])

    def test_resolve_probe_is_idempotent_on_rows(self):
        self.repo()
        st = self.wave.load_state(self.state)
        st['batches']['b011']['rows'].append(dict(self.ROW))
        self.wave.save_state(self.state, st)
        rc, out = self.resolve()
        self.assertEqual(rc, 0, out)
        b = self.wave.load_state(self.state)['batches']['b011']
        self.assertEqual([r['address'] for r in b['rows']], ['0x643CC0', '0x716E80'])
        self.assertEqual(b['verdicts']['0x716E80']['side'], 'ours')

    def test_resolve_probe_refuses_dump_decided_fork(self):
        self.repo()
        for side in ('fork', 'neither'):
            rc, out = self.resolve(side=side)
            self.assertEqual(rc, 1, out)
            self.assertIn('a fork/neither verdict decided by a dump reading', out)
            self.assertIn('only way to record it', out)
            self.assertNotIn('--allow-dump', out)
        self.assertEqual(len(self.probe_list()), 1)
        self.assertNotIn('0x716E80',
                         self.wave.load_state(self.state)['batches']['b011']['verdicts'])

    def test_resolve_probe_unknown_address(self):
        self.repo()
        rc, out = self.resolve(address='0x999999')
        self.assertEqual(rc, 2, out)
        self.assertEqual(out, '0x999999 is not on the probe list\n')
        self.repo(probes=False)
        self.assertEqual(self.resolve()[0], 2)
        self.repo()
        _write(os.path.join(self.root, 'docs', 'wso', 'probe-list.json'), json.dumps([
            {'address': '0x716E80', 'batch': 'b099', 'file': 'f', 'name': 'n'}]))
        rc, out = self.resolve()
        self.assertEqual(rc, 2, out)
        self.assertIn('b099', out)

    def test_resolve_probe_requires_evidence_phrase(self):
        for ev in (None, 'no phrase here; case dump-716E80 decides\n',
                   'disagreed with WSO at e8dd16a: x; case probe-9 decides\n'):
            self.repo(evidence=ev)
            rc, out = self.resolve()
            self.assertEqual(rc, 1, out)
            self.assertIn('docs/evidence/716E80.md', out)
            self.assertEqual(len(self.probe_list()), 1)
            self.assertEqual(self.wave.load_state(self.state)['batches']['b011']['rows'][0]
                             ['address'], '0x643CC0')

    # -- the audit paragraph ------------------------------------------------

    AUDIT_PARA = ('Audit sample (rule 3): seed rule3-2026-10-23 over 199 '
                  'dump-decided ours rows at 9fad8484; 10 drawn: 7 probed '
                  '(replay 6, oracle 1), 3 parked, 0 flips.\n')

    def audit(self, rows=None, **kw):
        if rows is None:
            rows = ([{'address': f'0x{i}', 'probe': 'replay', 'result': 'match'}
                     for i in range(6)]
                    + [{'address': '0x7', 'probe': 'oracle', 'result': 'match'}]
                    + [{'address': f'0x{i}', 'probe': 'park', 'result': 'parked'}
                       for i in (8, 9, 10)])
        data = {'rule': 3, 'seed': 'rule3-2026-10-23', 'state': '9fad8484',
                'pool': 199, 'drawn': 10, 'rows': rows}
        data.update(kw)
        _write(os.path.join(os.path.dirname(self.state), 'audit.json'),
               json.dumps(data))

    def scorecard(self):
        if not hasattr(self, 'root'):
            self.repo()
        report = os.path.join(self.tmp, 'xrec-report.md')
        rc, out = self.wave.write_scorecard(
            self.state, report, os.path.join(self.tmp, 'no-triage.json'), None)
        return rc, out, report

    def test_scorecard_renders_audit_sample(self):
        self.repo()
        self.audit()
        rc, out, report = self.scorecard()
        self.assertEqual(rc, 0, out)
        with open(report) as f:
            text = f.read()
        self.assertTrue(text.endswith('\n' + self.AUDIT_PARA), text)

    def test_scorecard_without_audit_file_unchanged(self):
        rc, out, report = self.scorecard()
        self.assertEqual(rc, 0, out)
        with open(report) as f:
            text = f.read()
        with open(self.state) as f:
            self.assertEqual(text, self.wave.scorecard_text(json.load(f))
                             + '\nCoverage: not measured\n')
        self.assertNotIn('Audit sample', text)

    def test_scorecard_rejects_malformed_audit(self):
        self.repo()
        for bad in ({'seed': 's', 'pool': 1, 'state': 'b', 'drawn': 1},
                    {'seed': 's', 'pool': 1, 'state': 'b', 'drawn': 1, 'rows': 'x'},
                    {'seed': 's', 'pool': 1, 'state': 'b', 'drawn': 1,
                     'rows': [{'probe': 'replay', 'result': 'maybe'}]},
                    {'seed': 's', 'pool': 1, 'state': 'b', 'drawn': 1,
                     'rows': [{'probe': 'guess', 'result': 'match'}]},
                    [], 'just a string', '"a json string"', '{not json'):
            _write(os.path.join(os.path.dirname(self.state), 'audit.json'),
                   bad if isinstance(bad, str) else json.dumps(bad))
            report = os.path.join(self.tmp, 'bad.md')
            rc, out = self.wave.write_scorecard(
                self.state, report, os.path.join(self.tmp, 'no-triage.json'), None)
            self.assertEqual(rc, 2, out)
            self.assertEqual(len(out.splitlines()), 1, out)
            self.assertFalse(os.path.exists(report))


class WaveProbeQueueTest(unittest.TestCase):
    """Task 28: `next --queue probes` cuts p<NNN> batches from the probe list;
    the brief quotes each row's reading and reason and the Candidates format."""
    PIN = 'e8dd16a750966af53f24daaf49dcb4fb13594c13'
    ENTRIES = [
        {'address': '0x478490', 'at': 't', 'batch': 'b013', 'file': 'src/CGameArea.cpp',
         'name': 'CGameArea::SetDawn', 'reading': 'fork', 'source': 'worker',
         'reason': 'exe sign-extends GetSong(0) via movsx'},
        {'address': '0x4258D0', 'at': 't', 'batch': 'b014', 'file': 'src/CBaldurChitin.cpp',
         'name': 'CBaldurChitin::OnMultiplayerSessionOpen', 'reading': 'neither', 'source': 'worker',
         'reason': 'the third chat clear is missing'},
        {'address': '0x602170', 'at': 't', 'batch': 'b014', 'file': 'src/CScreenConnection.cpp',
         'name': 'CScreenConnection::OnLobbyNewGameButtonClick', 'reading': 'fork',
         'source': 'worker', 'reason': 'the else branch is missing'}]

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.wave = load_tool('wave')
        self.dp = os.path.join(self.tmp, 'docs', 'wso', 'disagreements.json')
        _write(self.dp, json.dumps([
            {'address': e['address'], 'name': e['name'], 'file': e['file'],
             'category': 'both_changed_differ', 'their_len': 100 + i, 'our_len': 90}
            for i, e in enumerate(self.ENTRIES)]))
        _write(os.path.join(self.tmp, 'docs', 'wso', 'probe-list.json'), json.dumps(self.ENTRIES))
        self.wave.save_state(os.path.join(self.tmp, 'wave-state.json'), {
            'fork_base': self.PIN, 'batches': {
                'b013': {'rows': [], 'files': [], 'status': 'closed', 'verdicts': {},
                         'branch': 'p3/wso-b013', 'fork_base': 'a' * 40},
                'b014': {'rows': [], 'files': [], 'status': 'closed', 'verdicts': {},
                         'branch': 'p3/wso-b014'}}})
        self.state = os.path.join(self.tmp, 'probe-state.json')

    def next(self, size=20):
        with mock.patch.object(self.wave, '_cut_worktree', return_value=('/wt', 'new branch')) as cut:
            rc, out = self.wave.next_batch(
                self.dp, self.state, size, queue='probes', repo=self.tmp, base='first',
                claims_path=os.path.join(self.tmp, 'claims.json'))
        self.cut = cut
        return rc, out

    def batches(self):
        return self.wave.load_state(self.state)['batches']

    def test_the_queue_is_registered_with_its_own_state_status_and_template(self):
        q = self.wave.QUEUES['probes']
        self.assertEqual((q['prefix'], q['kind'], q['triage']), ('p', 'probes', False))
        self.assertEqual(os.path.basename(q['state']), 'probe-state.json')
        self.assertEqual(q['status'], 'status-probes.json')
        self.assertEqual(os.path.basename(q['template']), 'probe-brief-template.md')
        self.assertTrue(os.path.isfile(q['template']))
        self.assertTrue(driver.status_rel('probes').endswith('driver/status-probes.json'))

    def test_next_cuts_a_batch_from_the_probe_list_and_marks_the_rows_assigned(self):
        rc, out = self.next()
        self.assertEqual(rc, 0, out)
        self.assertIn('p001 assigned: 3 rows, 3 files, branch p3/wso-p001', out)
        self.assertIn('worktree /wt (new branch)', out)
        self.assertEqual(self.cut.call_args[0][1:3], ('p3/wso-p001', 'first'))
        b = self.batches()['p001']
        self.assertEqual((b['status'], b['branch']), ('assigned', 'p3/wso-p001'))
        self.assertEqual(sorted(r['address'] for r in b['rows']),
                         ['0x4258D0', '0x478490', '0x602170'])
        row = next(r for r in b['rows'] if r['address'] == '0x478490')
        self.assertEqual((row['reading'], row['reason'], row['origin']),
                         ('fork', 'exe sign-extends GetSong(0) via movsx', 'b013'))
        self.assertEqual(row['fork_base'], 'a' * 40)       # its original batch's pin
        self.assertIn(b['fork_base'], ('a' * 40, self.PIN))   # the first row's pin: the batch default
        # the rows are assigned: the next cut finds nothing
        rc, out = self.next()
        self.assertEqual(rc, 2, out)
        self.assertTrue(out.startswith('nothing left'), out)

    def test_a_batch_without_a_pin_uses_the_early_batches_pin_not_the_states_current_one(self):
        st = self.wave.load_state(os.path.join(self.tmp, 'wave-state.json'))
        st['fork_base'] = 'c' * 40
        self.wave.save_state(os.path.join(self.tmp, 'wave-state.json'), st)
        self.next()
        rows = {r['address']: r for r in self.batches()['p001']['rows']}
        self.assertEqual(rows['0x4258D0']['fork_base'], self.wave.DEFAULT_FORK_BASE)   # b014: none
        self.assertEqual(rows['0x478490']['fork_base'], 'a' * 40)                        # b013's own
        self.assertNotEqual(rows['0x4258D0']['fork_base'], 'c' * 40)    # the state's current pin

    def _closed_with_released_row(self, probed):
        for sc in ('world_entry', 'first_fight'):
            _write(os.path.join(self.tmp, 'scenarios', sc + '.txt'), 'quit\n')
        entries = [dict(e) for e in self.ENTRIES[:1]]
        entries[0]['probed'] = probed
        _write(os.path.join(self.tmp, 'docs', 'wso', 'probe-list.json'), json.dumps(entries))
        self.wave.save_state(self.state, {'batches': {'p001': {
            'rows': [{'address': '0x478490', 'file': 'src/CGameArea.cpp', 'released': True,
                      'outcome': 'kept'}], 'files': ['src/CGameArea.cpp'], 'status': 'closed',
            'verdicts': {}, 'branch': 'p3/wso-p001'}}})

    def cov(self, *a, **kw):
        return CoverageTest.cov(self, *a, **kw)

    def test_a_released_row_returns_only_for_a_new_scenario_or_a_moved_pin(self):
        pin = 'a' * 40      # b013's own pin: the pin of 0x478490
        for probed, hits, want in (
                ({'batch': 'p001', 'scenarios': ['world_entry'], 'pin': pin},
                 {'world_entry': {'0x478490': 2}}, False),          # the same set again
                ({'batch': 'p001', 'scenarios': ['world_entry'], 'pin': pin},
                 {'world_entry': {'0x478490': 2}, 'first_fight': {'0x478490': 1}}, True),   # a new one
                ({'batch': 'p001', 'scenarios': ['world_entry'], 'pin': 'b' * 40},
                 {'world_entry': {'0x478490': 2}}, True),           # the pin moved
                (None, {'world_entry': {'0x478490': 2}}, False)):   # never stamped: stays released
            self._closed_with_released_row(probed) if probed else self._closed_with_released_row({})
            self.cov(hits, hooked=['0x478490'])
            rc, out = self.next()
            self.assertEqual(rc == 0, want, (probed, hits, out))
            if want:
                self.assertIn('p002 assigned: 1 rows', out)

    def test_the_re_offer_rule_does_not_loop_on_what_the_phase_stamped(self):
        pin = 'a' * 40
        hits = {'world_entry': {'0x478490': 2}, 'first_fight': {'0x478490': 1}}
        # a fork row kept after a one-scenario run that two scenarios hit: its hits were
        # stamped with the run, so the same map never offers it again
        stamp = {'batch': 'p001', 'scenarios': ['world_entry'], 'pin': pin,
                 'hits': ['first_fight', 'world_entry']}
        self._closed_with_released_row(stamp)
        self.cov(hits, hooked=['0x478490'])
        rc, out = self.next()
        self.assertEqual(rc, 2, out)
        # a neither (hand-ruling) row with hits is not re-offered on a scenario change ...
        self._closed_with_released_row({'batch': 'p001', 'scenarios': [], 'hits': [], 'pin': pin,
                                        'hand': True})
        rc, out = self.next()
        self.assertEqual(rc, 2, out)
        # ... only on a pin move
        self._closed_with_released_row({'batch': 'p001', 'scenarios': [], 'hits': [],
                                        'pin': 'b' * 40, 'hand': True})
        rc, out = self.next()
        self.assertEqual(rc, 0, out)
        # a row stamped with empty hits (measured with no map) is not re-cut for a
        # scenario that already ran
        self._closed_with_released_row({'batch': 'p001', 'scenarios': ['world_entry'],
                                        'hits': [], 'pin': pin})
        self.cov({'world_entry': {'0x478490': 2}}, hooked=['0x478490'])
        rc, out = self.next()
        self.assertEqual(rc, 2, out)
        self.cov(hits, hooked=['0x478490'])
        # a hitting scenario the stamp's map did not have is a reason
        self._closed_with_released_row(dict(stamp, hits=['world_entry']))
        rc, out = self.next()
        self.assertEqual(rc, 0, out)

    def test_probe_hits_lists_the_scenarios_the_map_gives_a_row(self):
        self._closed_with_released_row({'batch': 'p001'})
        self.cov({'world_entry': {'0x478490': 2}, 'first_fight': {'0x478490': 1}},
                 hooked=['0x478490'])
        row = {'address': '0x478490', 'file': 'src/CGameArea.cpp'}
        self.assertEqual(self.wave.probe_hits(row, self.dp, None, self.tmp, self.tmp),
                         ['first_fight', 'world_entry'])
        os.unlink(os.path.join(self.tmp, 'docs', 'wso', 'coverage.json'))
        self.assertEqual(self.wave.probe_hits(row, self.dp, None, self.tmp, self.tmp), [])

    def test_an_open_batch_still_holds_its_row_even_with_a_new_scenario(self):
        pin = 'a' * 40
        self._closed_with_released_row({'batch': 'p001', 'scenarios': [], 'pin': pin})
        st = self.wave.load_state(self.state)
        st['batches']['p001']['status'] = 'assigned'
        self.wave.save_state(self.state, st)
        self.cov({'world_entry': {'0x478490': 2}}, hooked=['0x478490'])
        rc, out = self.next()
        self.assertEqual(rc, 2, out)

    def test_next_takes_at_most_size_rows_and_ids_count_up(self):
        rc, out = self.next(size=2)
        self.assertEqual(rc, 0, out)
        self.assertIn('p001 assigned: 2 rows', out)
        rc, out = self.next(size=2)
        self.assertEqual(rc, 0, out)
        self.assertIn('p002 assigned: 1 rows', out)
        self.assertEqual(sorted(self.batches()), ['p001', 'p002'])

    def test_next_leaves_the_other_queues_state_alone_and_skips_owned_files(self):
        self.wave.save_state(os.path.join(self.tmp, 'import-state.json'), {'batches': {'i001': {
            'rows': [], 'files': ['src/CGameArea.cpp'], 'status': 'assigned', 'verdicts': {},
            'branch': 'p3/wso-i001'}}})
        rc, out = self.next()
        self.assertEqual(rc, 0, out)
        self.assertNotIn('0x478490', [r['address'] for r in self.batches()['p001']['rows']])
        self.assertEqual(sorted(self.wave.load_state(
            os.path.join(self.tmp, 'import-state.json'))['batches']), ['i001'])

    def test_brief_quotes_each_rows_reading_and_reason_and_the_candidates_format(self):
        self.next()
        rc, text = self.wave.render_brief(
            self.wave.QUEUES['probes']['template'], self.state, 'p001',
            bundle_dir=os.path.join(self.tmp, 'b'), bundle_fn=lambda a: 'x')
        self.assertEqual(rc, 0, text)
        self.assertNotIn('{{', text)
        self.assertIn('`0x478490` **CGameArea::SetDawn** (src/CGameArea.cpp; earlier reading '
                      '`fork`, left by b013; fork pin `' + 'a' * 40 + '`)', text)
        self.assertIn('   - reason: exe sign-extends GetSong(0) via movsx', text)
        self.assertIn('earlier reading `neither`', text)
        self.assertIn('candidate <0xADDR> fork <one-line reason>', text)
        self.assertIn('candidate <0xADDR> neither <one-line reason>', text)
        self.assertIn('## Candidates', text)
        self.assertIn('Imported-From: WillScarlettOhara/iwd2-re@<40-char sha>', text)
        self.assertIn('fork pin `%s`)' % self.PIN, text)     # the other rows' own pin
        self.assertIn('git show\n   <pin>:<path>', text)
        self.assertIn('p3/wso-p001', text)
        self.assertIn('python3 -I tools/wave.py selfcheck --batch p001', text)
        self.assertIn('Do NOT write the deciding sentence', text)
        self.assertIn('case frida-<batch>-<scenario> decides', text)
        # a neither row is not built; the rules of the wave-1 brief carry over
        self.assertIn('A `neither` reading is not built', text)
        for rule in ('Never rewrite history', 'Never push', 'Selfcheck last',
                     'Nothing on the desktop', 'Do not edit `docs/MAP.md`'):
            self.assertIn(rule, text.replace('**', ''), rule)
        self.assertIn('No verdicts', text.replace('**', ''))

    def test_resolve_probe_refuses_an_unknown_measured(self):
        rc, out = self.wave.resolve_probe('0x478490', 'fork', 'frida-p001-x', measured='guess')
        self.assertEqual(rc, 2)
        self.assertIn('measured must be one of', out)

    def test_cli_close_kind_probes_reads_the_probe_state(self):
        out = io.StringIO()
        with mock.patch.object(self.wave, 'close_batch', return_value=(0, 'ok\n')) as cb, \
                mock.patch('sys.stdout', out):
            self.assertEqual(self.wave.main(['close', 'p001', '--kind', 'probes']), 0)
        self.assertEqual(cb.call_args.kwargs['state_path'], self.wave.PROBE_STATE_PATH)
        self.assertEqual(cb.call_args.kwargs['kind'], 'probes')
        with mock.patch.object(self.wave, 'close_batch', return_value=(0, 'ok\n')) as cb, \
                mock.patch('sys.stdout', io.StringIO()):
            self.wave.main(['close', 'b001'])
        self.assertNotIn('state_path', cb.call_args.kwargs)     # the other kinds are untouched

    def test_selfcheck_of_a_probe_batch_reads_candidates(self):
        repo = os.path.join(self.tmp, 'sc')
        os.makedirs(repo)

        def g(*a):
            return subprocess.run(['git', '-C', repo, '-c', 'user.name=T', '-c', 'user.email=t@e.com',
                                   '-c', 'commit.gpgsign=false', *a], check=True,
                                  capture_output=True, text=True)
        g('init', '-q', '-b', 'first')
        _write(os.path.join(repo, 'docs/wso/probe-state.json'), json.dumps({'batches': {'p001': {
            'branch': 'p3/wso-p001', 'rows': [{'address': '0x401000', 'reading': 'neither'}]}}}))
        _write(os.path.join(repo, 'src/a.cpp'), 'a\n')
        g('add', '-A')
        g('commit', '-q', '-m', 'base')
        g('checkout', '-q', '-b', 'p3/wso-p001')
        self.assertEqual(driver.selfcheck('p001', repo, '## Candidates\n\ncandidate 0x401000 neither r\n'), [])
        probs = driver.selfcheck('p001', repo, '## Notes\n\nnone\n')
        self.assertEqual(len(probs), 1, probs)
        self.assertIn('0x401000: not accounted for in the report', probs[0])
        probs = driver.selfcheck('p001', repo, '## Verdicts\n\nverdict 0x401000 ours case x\n\n'
                                 '## Candidates\n\ncandidate 0x401000 neither r\n')
        self.assertTrue(any('a probe report has no ## Verdicts' in p for p in probs), probs)


class WaveUndecideTest(unittest.TestCase):
    """wave.py undecide (a batch row onto the probe list) and line-buffered
    output."""

    setUp = WaveResolveTest.setUp
    ROW = WaveResolveTest.ROW
    resolve = WaveResolveTest.resolve
    probe_list = WaveResolveTest.probe_list

    def repo(self, status='assigned', probes=()):
        self.root = os.path.join(self.tmp, 'repo')
        shutil.rmtree(self.root, ignore_errors=True)
        wso = os.path.join(self.root, 'docs', 'wso')
        first = dict(self.ROW, address='0x643CC0', name='Render')
        _write(os.path.join(wso, 'disagreements.json'),
               json.dumps([first, self.ROW]))
        self.state = os.path.join(wso, 'wave-state.json')
        self.wave.save_state(self.state, {'batches': {'b011': {
            'rows': [first, dict(self.ROW)],
            'files': ['src/CGameSprite.cpp'],
            'branch': 'p3/wso-b011', 'status': status, 'assigned_at': 't',
            'verdicts': {'0x716E80': {'side': 'ours', 'case': 'probe-1',
                                      'losing_kind': 'trace'}}}}})
        _write(os.path.join(wso, 'probe-list.json'), json.dumps(list(probes)))
        _write(os.path.join(self.root, 'docs', 'evidence', '716E80.md'),
               '---\nkind: oracle\n---\n\ndisagreed with WSO at e8dd16a: x; '
               'case probe-9 decides\n')

    def undecide(self, batch='b011', addr='0x716E80', reading='fork',
                 reason='cannot decide'):
        return self.wave.undecide(batch, addr, reading, reason,
                                  self.state, self.root)

    def snapshot(self):
        out = []
        for p in (self.state, os.path.join(self.root, 'docs', 'wso',
                                           'probe-list.json')):
            with open(p, 'rb') as f:
                out.append(f.read())
        return out

    def refuses(self, **kw):
        before = self.snapshot()
        rc, out = self.undecide(**kw)
        self.assertEqual(rc, 2, out)
        self.assertEqual(self.snapshot(), before)
        return out

    def test_undecide_moves_row_and_resolve_returns_it(self):
        self.repo()
        rc, out = self.undecide()
        self.assertEqual(rc, 0, out)
        self.assertIn('dropped its verdict', out)
        self.assertIn('merge base', out)
        self.assertIn('resolve', out)
        b = self.wave.load_state(self.state)['batches']['b011']
        self.assertEqual([r['address'] for r in b['rows']], ['0x643CC0'])
        self.assertEqual(b['verdicts'], {})
        entry, = self.probe_list()
        self.assertEqual(sorted(entry), ['address', 'at', 'batch', 'file',
                                         'name', 'reading', 'reason', 'source'])
        self.assertEqual((entry['source'], entry['batch'], entry['reading'],
                          entry['reason'], entry['file'], entry['name']),
                         ('coordinator', 'b011', 'fork', 'cannot decide',
                          'src/CGameSprite.cpp', 'CGameSprite::sub_716E80'))
        rc, out = self.resolve(case='probe-9')
        self.assertEqual(rc, 0, out)
        b = self.wave.load_state(self.state)['batches']['b011']
        self.assertEqual([r['address'] for r in b['rows']],
                         ['0x643CC0', '0x716E80'])
        self.assertEqual(self.probe_list(), [])

    def test_undecide_refusals_write_nothing(self):
        self.repo()
        self.assertIn('no batch b999', self.refuses(batch='b999'))
        self.assertIn('not a row', self.refuses(addr='0x111111'))
        self.assertIn('fork or neither', self.refuses(reading='ours'))
        self.assertIn('reason', self.refuses(reason=' '))
        self.repo(status='closed')
        self.assertIn('b011 is closed; a closed row is reopened through the '
                      'probe list by hand', self.refuses())
        self.repo(probes=[{'address': '0x716e80', 'at': 't', 'batch': 'b011',
                           'file': 'f', 'name': 'n', 'reading': 'fork',
                           'reason': 'r', 'source': 'worker'}])
        self.assertIn('already on the probe list', self.refuses())

    def test_main_line_buffers_when_not_a_tty(self):
        for tty, calls in ((False, 2), (True, 0)):
            with mock.patch.object(sys, 'stdout') as so, \
                 mock.patch.object(sys, 'stderr') as se:
                so.isatty.return_value = tty
                se.isatty.return_value = tty
                self.wave.main(['bogus-command'])
            got = so.reconfigure.call_count + se.reconfigure.call_count
            self.assertEqual(got, calls)
            if not tty:
                so.reconfigure.assert_called_with(line_buffering=True)

    def test_coverage_dry_to_a_pipe_still_prints(self):
        r = subprocess.run([sys.executable, '-I', os.path.join(
            os.path.dirname(os.path.abspath(__file__)), '..', 'tools',
            'wave.py'), 'coverage', '--dry'], capture_output=True, text=True)
        self.assertTrue(r.stdout or r.stderr)


class WaveCloseRulesTest(unittest.TestCase):
    """Task 16: close refuses dump-decided fork/neither verdicts, syncs the
    base before it merges, and the checked-out base follows the ref."""

    setUp = WaveTest.setUp
    write_disagreements = WaveTest.write_disagreements
    next = WaveTest.next
    batches = WaveTest.batches
    git = WaveTest.git
    init_repo = WaveTest.init_repo
    EVIDENCE = WaveTest.EVIDENCE
    write_evidence = WaveTest.write_evidence
    commit_worktree = WaveTest.commit_worktree
    gates = WaveTest.gates
    first_sha = WaveTest.first_sha

    def ready(self, render=('ours', 'probe-11'), draw=('fork', 'probe-9')):
        self.init_repo()
        self.write_evidence()
        self.commit_worktree()
        for addr, (side, case) in (('0x643CC0', render), ('0x643CD0', draw)):
            self.assertEqual(self.wave.record_verdict(
                self.state, self.root, 'b001', addr, side, case)[0], 0)

    def close(self, **kw):
        return self.wave.close_batch(self.state, self.root, 'b001', gate=False, **kw)

    def ledger(self, text):
        path = os.path.join(self.tmp, 'ledger.md')
        with open(path, 'w') as f:
            f.write(text)
        return path

    def test_close_refuses_dump_decided_fork_verdict(self):
        self.ready(draw=('fork', 'dump-3'))
        first = self.first_sha()
        rc, out = self.close()
        self.assertEqual(rc, 1, out)
        self.assertIn('0x643CD0: a fork/neither verdict decided by a dump reading '
                      '(dump-3); probe before import, or --allow-dump <ruling id>', out)
        self.assertNotIn('0x643CC0', out)
        self.assertEqual(self.first_sha(), first)
        self.assertEqual(self.batches()['b001']['status'], 'assigned')

    def test_close_refuses_dump_decided_neither_verdict(self):
        self.ready(draw=('neither', 'readout-643CD0'))
        rc, out = self.close()
        self.assertEqual(rc, 1, out)
        self.assertIn('a fork/neither verdict decided by a dump reading (readout-643CD0)', out)

    def test_close_passes_a_wrapped_deciding_sentence(self):
        self.ready()
        wrapped = ('---\nkind: replay\n---\n\n## WSO delta\n\n'
                   'disagreed with\nWSO at e8dd16a: the guard\ndiffers in both\n'
                   'builds and the replay\nshows it; case probe-9\ndecides.\n')
        for stem in ('643CC0', '643CD0'):
            with open(os.path.join(self.wt, 'docs', 'evidence', stem + '.md'), 'w') as f:
                f.write(wrapped)
        self.commit_worktree('wrap')
        rc, out = self.close()
        self.assertEqual(rc, 0, out)

    def _wave_trace_ready(self, measured_body='right'):
        """b001 with Render's evidence a driver-written frida trace of this
        batch (kind trace, the WSO delta sentence intact) and its body in src."""
        self.ready(render=('ours', 'dump-1'))
        frida = ('frida b001-world_entry orig:' + 'a' * 64 + ' ours:' + 'b' * 64 + ' compare=0')
        _write(os.path.join(self.wt, 'docs', 'evidence', '643CC0.md'),
               '---\naddress: 0x643CC0\nname: fn-643CC0\nkind: trace\ntrace_source: %s\n---\n\n'
               '## WSO delta\n\ndisagreed with WSO at e8dd16a: the guard differs; '
               'case dump-1 decides.\n' % frida)
        _write(os.path.join(self.wt, 'src', 'A.cpp'), self.RENDER_BODY)
        self.commit_worktree('frida: trace evidence for 1 row(s) measured equal (world_entry)')
        digest = load_tool('check_evidence').body_digest(self.wt, '0x643CC0')
        with open(self.state) as f:
            state = json.load(f)
        for r in state['batches']['b001']['rows']:
            if r['address'] == '0x643CC0' and measured_body:
                r['measured_body'] = digest if measured_body == 'right' else 'f' * 64
        with open(self.state, 'w') as f:
            json.dump(state, f)

    def test_close_accepts_a_wave_one_row_whose_evidence_became_frida_trace(self):
        # Task 20: the wave-1 Frida phase rewrote an equal row's front matter to
        # kind: trace and recorded the body it measured; close accepts it
        self._wave_trace_ready()
        rc, out = self.close()
        self.assertEqual(rc, 0, out)
        ce = load_tool('check_evidence')
        text = _slurp(os.path.join(self.wt, 'docs', 'evidence', '643CC0.md'))
        self.assertEqual(ce.front_matter(text)['kind'], 'trace')
        self.assertTrue(ce.TRACE_SOURCES[1].fullmatch(ce.front_matter(text)['trace_source']))

    def _refused_trace(self, recorded):
        self._wave_trace_ready(recorded)
        rc, out = self.close()
        self.assertEqual(rc, 1, out)
        self.assertIn('0x643CC0: body changed after the Frida phase; edit the body back to the one '
                      "the driver's 'frida: trace evidence' commit measured, or put the evidence "
                      'file back to its pre-phase content so the verdict stands on the reading', out)
        self.assertEqual(self.batches()['b001']['status'], 'assigned')

    def test_close_refuses_a_wave_one_trace_whose_body_changed_after_the_phase(self):
        self._refused_trace('wrong')

    def test_close_refuses_a_wave_one_trace_with_no_recorded_body(self):
        self._refused_trace(None)

    def test_import_close_refuses_a_touched_row_on_another_batchs_frida_trace(self):
        foreign = self.FRIDA.replace('b001-', 'i009-')
        self._import_ready(trace=())
        _write(os.path.join(self.wt, 'docs', 'evidence', '643CC0.md'),
               '---\naddress: 0x643CC0\nname: fn\nkind: trace\ntrace_source: %s\n---\n\nnotes\n' % foreign)
        _write(os.path.join(self.wt, 'docs', 'evidence', '643CD0.md'),
               '---\naddress: 0x643CD0\nname: fn\nkind: replay\n---\n\nnotes\n')
        self.commit_worktree('foreign trace')
        rc, out = self.close(kind='import')
        self.assertEqual(rc, 1, out)
        self.assertIn("its frida trace is another batch's (i009-world_entry)", out)
        # it passes only for the body this batch's phase recorded
        with open(self.state) as f:
            state = json.load(f)
        for r in state['batches']['b001']['rows']:
            if r['address'] == '0x643CC0':
                r['measured_body'] = load_tool('check_evidence').body_digest(self.wt, '0x643CC0')
        with open(self.state, 'w') as f:
            json.dump(state, f)
        rc, out = self.close(kind='import')
        self.assertNotIn("another batch's", out)

    def test_import_close_refuses_a_dependency_on_another_batchs_frida_trace(self):
        foreign = self.FRIDA.replace('b001-', 'i009-')
        self._import_ready(trace=('0x643CC0',), evidence=('0x643CD0',))
        with open(os.path.join(self.wt, 'src', 'A.cpp'), 'a') as f:
            f.write('// 0x643CE0\nint Dep()\n{\n  return 1;\n}\n')
