        clean = lambda body: body + 'HITS-FINAL yes\nRESULT: CLEAN\n'
        fake = self._status_fake(self.tmp, {
            ('world_entry', 1): [clean('HITS fn_401000 1\n')],
            ('biography', 1): [clean('HITS fn_401000 1\n')]})
