        def fake(cmd, **kw):
            _write(os.path.join(self.tmp, 'scenarios', 'world_entry.txt'), 'edited during\nquit\n')
            return inner(cmd, **kw)
        res = coverage.run(['world_entry'], chunk=5, run=fake, root=self.tmp,
                           addresses=['0x401000'])
